create or replace function internal.current_user_role() returns text language plpgsql stable security definer set search_path = '' as $$ declare v_role text; begin select s.role into v_role from public.staff s where (s.user_id = (select auth.uid()) or (s.user_id is null and lower(s.email) = lower((select auth.jwt() ->> 'email')))) and s.status = 'active' limit 1; if v_role is not null then return v_role; end if; if exists (select 1 from public.parents p where (p.user_id = (select auth.uid()) or (p.user_id is null and lower(p.email) = lower((select auth.jwt() ->> 'email')))) and p.status = 'active') then return 'parent'; end if; return null; end; $$;
create or replace function internal.has_role(allowed_roles text[]) returns boolean language plpgsql stable security definer set search_path = '' as $$ begin return exists (select 1 from public.staff s where (s.user_id = (select auth.uid()) or (s.user_id is null and lower(s.email) = lower((select auth.jwt() ->> 'email')))) and s.status = 'active' and s.role = any(allowed_roles)) or exists (select 1 from public.parents p where (p.user_id = (select auth.uid()) or (p.user_id is null and lower(p.email) = lower((select auth.jwt() ->> 'email')))) and p.status = 'active' and 'parent' = any(allowed_roles)); end; $$;
create or replace function internal.is_academy_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.staff s where (s.user_id = (select auth.uid()) or (s.user_id is null and lower(s.email) = lower((select auth.jwt() ->> 'email')))) and s.role = 'manager' and s.status = 'active'); $$;
create or replace function internal.is_academy_member() returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.staff s where (s.user_id = (select auth.uid()) or (s.user_id is null and lower(s.email) = lower((select auth.jwt() ->> 'email')))) and s.status = 'active'); $$;
create or replace function internal.is_active_member() returns boolean language plpgsql stable security definer set search_path = '' as $$ begin return exists (select 1 from public.staff s where (s.user_id = (select auth.uid()) or (s.user_id is null and lower(s.email) = lower((select auth.jwt() ->> 'email')))) and s.status = 'active') or exists (select 1 from public.parents p where (p.user_id = (select auth.uid()) or (p.user_id is null and lower(p.email) = lower((select auth.jwt() ->> 'email')))) and p.status = 'active'); end; $$;
create or replace function internal.is_coach_of_team(p_team_id text) returns boolean language plpgsql stable security definer set search_path = '' as $$ begin if p_team_id is null or nullif(trim(p_team_id),'') is null then return false; end if; return exists (select 1 from public.teams t join public.staff s on s.id=t.coach_id where t.id=p_team_id and s.role='coach' and s.status='active' and (s.user_id=(select auth.uid()) or (s.user_id is null and lower(s.email)=lower((select auth.jwt() ->> 'email'))))); end; $$;
create or replace function internal.is_coach_of_parent(p_parent_id text) returns boolean language plpgsql stable security definer set search_path = '' as $$ begin if p_parent_id is null or nullif(trim(p_parent_id),'') is null then return false; end if; return exists (select 1 from public.players p where p.parent_id=p_parent_id and internal.is_coach_of_team(p.team_id)); end; $$;
create or replace function internal.is_parent_of_player(p_player_id text) returns boolean language plpgsql stable security definer set search_path = '' as $$ begin if p_player_id is null or nullif(trim(p_player_id),'') is null then return false; end if; return exists (select 1 from public.players p join public.parents pa on pa.id=p.parent_id where p.id=p_player_id and pa.user_id=(select auth.uid())); end; $$;
create or replace function internal.record_subscription_payment(p_subscription_id text,p_amount numeric,p_payment_method text,p_transaction_date text default null,p_description text default null) returns public.transactions language plpgsql security definer set search_path = '' as $$ declare v_sub public.subscriptions%rowtype; v_txn public.transactions%rowtype; v_role text; v_now_text text; begin if (select auth.uid()) is null then raise exception 'Authentication required'; end if; v_role:=internal.current_user_role(); if v_role not in ('manager','accountant') then raise exception 'Only manager or accountant can record payments'; end if; if p_amount is null or p_amount<=0 then raise exception 'Payment amount must be greater than zero'; end if; if nullif(trim(coalesce(p_payment_method,'')),'') is null then raise exception 'Payment method is required'; end if; select * into v_sub from public.subscriptions where id=p_subscription_id for update; if not found then raise exception 'Subscription not found'; end if; if v_sub.status='paid' then raise exception 'Subscription is already paid'; end if; if p_amount<>v_sub.amount then raise exception 'Payment amount must equal subscription amount'; end if; v_now_text:=coalesce(nullif(trim(coalesce(p_transaction_date,'')),''),to_char(current_date,'YYYY-MM-DD')); update public.subscriptions set status='paid',payment_method=trim(p_payment_method),paid_at=to_char(now(),'YYYY-MM-DD"T"HH24:MI:SSOF') where id=v_sub.id; insert into public.transactions(id,type,category,amount,transaction_date,description,recorded_by,subscription_id,player_id) values ('txn-'||floor(extract(epoch from clock_timestamp())*1000)::bigint::text||'-'||substr(md5(random()::text),1,8),'revenue','subscription',p_amount,v_now_text,coalesce(nullif(trim(coalesce(p_description,'')),''),'سداد اشتراك '||v_sub.id),coalesce((select name from public.staff where user_id=(select auth.uid()) limit 1),coalesce((select auth.jwt() ->> 'email'),'')),v_sub.id,v_sub.player_id) returning * into v_txn; return v_txn; end; $$;
